#!/bin/bash
set -e

# Qwen2.5-VL-3B + hybridkv_repackKV on MileBench image tasks.
export TOKENIZERS_PARALLELISM=false

export OMP_NUM_THREADS=4
export MKL_NUM_THREADS=4
export NUMEXPR_NUM_THREADS=4
export PYTHONPATH=/root/autodl-tmp/HybridKV-opensource:/root/autodl-tmp/HybridKV-opensource/hybridkv:${PYTHONPATH:-}
export LD_LIBRARY_PATH=/root/miniconda3/envs/hybridkv/lib/python3.12/site-packages/torch/lib:/root/miniconda3/envs/hybridkv/lib:${LD_LIBRARY_PATH:-}

export HF_HOME=/root/autodl-tmp/HybridKV-opensource/data/huggingface_cache
export HF_DATASETS_CACHE=${HF_HOME}/datasets
export HUGGINGFACE_HUB_CACHE=${HF_HOME}/hub
export HF_ENDPOINT=${HF_ENDPOINT:-https://hf-mirror.com}
mkdir -p /root/autodl-tmp/HybridKV-opensource/data/milebench ${HF_DATASETS_CACHE} ${HUGGINGFACE_HUB_CACHE}

GEN_SCRIPT_PATH=generate.py
EVAL_SCRIPT_PATH=evaluate.py
DATA_DIR=/root/autodl-tmp/HybridKV-opensource/data/milebench
MODEL_CONFIG_PATH=configs/qwen2_5_vl_model_configs.yaml
gpu_num=1

KV_MODE=attn_entropy_TextAVGMerge
MODEL=qwen2.5-vl-3b
export MODEL_TYPE=${MODEL}

methods=("hybridkv_repackKV")
budget_ratios=(0.1)
datasets=("CLEVR-Change" "DocVQA" "MMCoQA" "MultiModalQA" "SlideVQA" "Spot-the-Diff" "WebQA" "WikiVQA")

export PYTORCH_CUDA_ALLOC_CONF=expandable_segments:True
export CUDA_HOME=/usr/local/cuda
export PATH=${CUDA_HOME}/bin:${PATH}
export CUDA_VISIBLE_DEVICES=${CUDA_VISIBLE_DEVICES:-0}
head_classify="head_ada"
budget_method="head_ada"
export BUDGET_METHOD=${budget_method}
export HEAD_CLASSIFY=${head_classify}

# hybridkv_repackKV controls. These names are kept compatible with the copied implementation.
export HYBRID_DECOUPLE_CHUNK_SIZE=${HYBRID_DECOUPLE_CHUNK_SIZE:-8}
export HYBRID_DECOUPLE_COMPRESS_RATIO=${HYBRID_DECOUPLE_COMPRESS_RATIO:-0.50}
export K_DIFF_ALPHA=${K_DIFF_ALPHA:-2}
export HYBRID_DECOUPLE_K_DIFF_ALPHA=${HYBRID_DECOUPLE_K_DIFF_ALPHA:-${K_DIFF_ALPHA}}
export HYBRID_DECOUPLE_MAX_GROUP_SIZE=${HYBRID_DECOUPLE_MAX_GROUP_SIZE:-0}
export HYBRID_DECOUPLE_BLOCK_META_WEIGHT=${HYBRID_DECOUPLE_BLOCK_META_WEIGHT:-uniform}
export HYBRID_DECOUPLE_STATIC_MERGE_SCOPE=${HYBRID_DECOUPLE_STATIC_MERGE_SCOPE:-visual}
export HYBRID_DECOUPLE_K_MERGE_SPACE=${HYBRID_DECOUPLE_K_MERGE_SPACE:-${K_MERGE_SPACE:-raw_reapply}}
export HYBRID_DECOUPLE_SIMHEAD_ENABLE=${HYBRID_DECOUPLE_SIMHEAD_ENABLE:-1}
export HYBRID_DECOUPLE_SIMHEAD_MERGE_RATIO=${HYBRID_DECOUPLE_SIMHEAD_MERGE_RATIO:-0.50}
export HYBRID_DECOUPLE_SIMHEAD_SIM_SPACE=${HYBRID_DECOUPLE_SIMHEAD_SIM_SPACE:-raw}
export HYBRID_DECOUPLE_VERBOSE=${HYBRID_DECOUPLE_VERBOSE:-0}
export HYBRIDKV_VERBOSE=${HYBRIDKV_VERBOSE:-0}

for method in ${methods[@]}; do
    for budget_ratio in ${budget_ratios[@]}; do
        for dataset_name in ${datasets[@]}; do
            if [ ${dataset_name} = "MMCoQA" ] || [ ${dataset_name} = "NeedleInAHaystack" ] || [ ${dataset_name} = "GPR1200" ]; then
                BATCH_SIZE=1
            else
                BATCH_SIZE=24
            fi

            mkdir -p logs/image/${MODEL}
            echo "$(date '+%F %T'): Generation of ${MODEL} ${method} to ${dataset_name}"

            accelerate launch --config_file ./configs/accelerate_configs.yaml \
                --main_process_port ${MAIN_PROCESS_PORT:-29596} \
                --num_machines 1 \
                --machine_rank 0 \
                --num_processes ${gpu_num} \
                --deepspeed_multinode_launcher standard \
                ${GEN_SCRIPT_PATH} \
                --data_dir ${DATA_DIR} \
                --dataset_name ${dataset_name} \
                --model_name ${MODEL} \
                --output_dir outputs \
                --batch-image ${BATCH_SIZE} \
                --model_configs ${MODEL_CONFIG_PATH} \
                --overwrite \
                --kv_mode ${KV_MODE} \
                --method ${method} \
                --budget_ratio ${budget_ratio}

            python ${EVAL_SCRIPT_PATH} \
                --data-dir ${DATA_DIR} \
                --dataset ${dataset_name} \
                --result-dir outputs/${MODEL}/${method}/${budget_ratio}/${head_classify}/${budget_method}

            python score.py \
                --result-dir outputs \
                --models ${MODEL}/${method}/${budget_ratio}/${head_classify}/${budget_method}
        done
    done
done

